PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE COLLATE NOCASE,phone TEXT,password_hash TEXT NOT NULL,customer_type TEXT NOT NULL DEFAULT 'b2c' CHECK(customer_type IN('b2b','b2c')),business_name TEXT,gstin TEXT,account_status TEXT NOT NULL DEFAULT 'pending' CHECK(account_status IN('pending','approved','blocked')),role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN('customer','admin')),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,sku TEXT UNIQUE,name TEXT NOT NULL,category TEXT NOT NULL,description TEXT DEFAULT '',active INTEGER DEFAULT 1,sort_order INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS variants(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,sku TEXT,name TEXT NOT NULL,options_json TEXT NOT NULL DEFAULT '{}',supplier_rate_inclusive REAL NOT NULL CHECK(supplier_rate_inclusive>=0),gst_rate_percent REAL NOT NULL DEFAULT 18 CHECK(gst_rate_percent BETWEEN 0 AND 100),quantity_unit TEXT NOT NULL DEFAULT 'pack',active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS pricing_settings(id INTEGER PRIMARY KEY CHECK(id=1),b2b_markup_percent REAL NOT NULL DEFAULT 20,b2b_minimum_addition REAL NOT NULL DEFAULT 50,b2c_markup_percent REAL NOT NULL DEFAULT 100);
INSERT OR IGNORE INTO pricing_settings(id) VALUES(1);
CREATE TABLE IF NOT EXISTS enquiries(id INTEGER PRIMARY KEY,enquiry_number TEXT NOT NULL UNIQUE,customer_id INTEGER NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'new',items_json TEXT NOT NULL,subtotal_inclusive REAL NOT NULL,customer_notes TEXT,contact_phone TEXT,delivery_location TEXT,idempotency_key TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(customer_id,idempotency_key));
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY,order_number TEXT NOT NULL UNIQUE,enquiry_id INTEGER REFERENCES enquiries(id),customer_id INTEGER NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'confirmed',total_inclusive REAL NOT NULL DEFAULT 0,payment_status TEXT NOT NULL DEFAULT 'unpaid',notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),amount REAL NOT NULL,method TEXT NOT NULL,reference TEXT,status TEXT NOT NULL DEFAULT 'recorded',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS artwork_files(id INTEGER PRIMARY KEY,enquiry_id INTEGER REFERENCES enquiries(id),customer_id INTEGER NOT NULL REFERENCES users(id),stored_name TEXT NOT NULL,original_name TEXT NOT NULL,mime_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,review_status TEXT NOT NULL DEFAULT 'pending',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_enquiries_customer ON enquiries(customer_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_orders_customer ON orders(customer_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_variants_product ON variants(product_id,active);